
'use strict';
const ASSETS={"background": "data:image/png;base64,", "body": "data:image/png;base64,", "flap": "data:image/png;base64,", "algyrlar": "data:image/png;base64,", "tapqyrlar": "data:image/png;base64,", "zerekter": "data:image/png;base64,", "zhuirikter": "data:image/png;base64,", "click": "data:audio/mpeg;base64,", "open": "data:audio/mpeg;base64,", "reveal": "data:audio/mpeg;base64,", "finish": "data:audio/mpeg;base64,"};
const ALL_GROUPS=[{name:'Алғырлар',key:'algyrlar',color:'#175ab0',symbol:'🦅'},{name:'Тапқырлар',key:'tapqyrlar',color:'#127856',symbol:'♫'},{name:'Зеректер',key:'zerekter',color:'#8251b0',symbol:'☀'},{name:'Жүйріктер',key:'zhuirikter',color:'#aa7216',symbol:'♞'}];
let GROUPS=[...ALL_GROUPS];
function setGroups(n){GROUPS=ALL_GROUPS.slice(0,n);document.documentElement.style.setProperty('--group-count',n);}
function shuffle(input,rng=Math.random){const a=[...input];for(let i=a.length-1;i>0;i--){const j=Math.floor(rng()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a}
class Division{
 constructor(names,mode,groupCount=4){this.groupCount=groupCount;this.names=[...names];this.mode=mode;this.cap=Array(groupCount).fill(Math.floor(names.length/groupCount));shuffle(Array.from({length:groupCount},(_,i)=>i)).slice(0,names.length%groupCount).forEach(i=>this.cap[i]++);this.deck=shuffle(this.cap.flatMap((n,i)=>Array(n).fill(i)));this.done=[];this.phase='choose';this.bag=null;this.version=1}
 assign(bag){if(this.phase!=='choose'||this.done.length>=this.names.length)return false;this.bag=bag;this.done.push(this.deck[this.done.length]);this.phase='result';return true}
 next(){if(this.phase!=='result')return;this.phase=this.done.length===this.names.length?'summary':'choose';this.bag=null}
 static restore(s){const gc=s?.groupCount??s?.cap?.length;if(!Number.isInteger(gc)||gc<2||gc>4)return null;if(!s||s.version!==1||!Array.isArray(s.names)||s.names.length<4||s.names.length>60||!s.names.every(n=>typeof n==='string'&&n.trim())||!['count','names'].includes(s.mode)||!Array.isArray(s.cap)||s.cap.length!==gc||!s.cap.every(Number.isInteger)||Math.max(...s.cap)-Math.min(...s.cap)>1||s.cap.reduce((a,b)=>a+b,0)!==s.names.length||!Array.isArray(s.deck)||s.deck.length!==s.names.length||!s.deck.every(x=>Number.isInteger(x)&&x>=0&&x<gc)||!s.cap.every((n,i)=>s.deck.filter(x=>x===i).length===n)||!Array.isArray(s.done)||s.done.length>s.names.length||!s.done.every((x,i)=>x===s.deck[i])||!['choose','result','summary'].includes(s.phase))return null;if(s.phase==='result'&&(!s.done.length||!Number.isInteger(s.bag)||s.bag<0||s.bag>=gc))return null;if(s.phase==='choose'&&s.done.length===s.names.length||s.phase==='summary'&&s.done.length!==s.names.length)return null;return Object.assign(Object.create(Division.prototype),s,{groupCount:gc})}
}
const $=id=>document.getElementById(id),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;const KEY='qorzhyn-v1-state',DRAFT='qorzhyn-v1-draft';let mode='count',state=null,saved=null,busy=false,epoch=0,confirmAction=null,sound=true;const timers=new Set();
const get=(k)=>{try{return localStorage.getItem(k)}catch(e){return null}},set=(k,v)=>{try{localStorage.setItem(k,v)}catch(e){}},remove=k=>{try{localStorage.removeItem(k)}catch(e){}};
sound=get('qorzhyn-sound')!=='off';document.documentElement.style.setProperty('--bg',`url("${ASSETS.background||''}")`);
const audio=Object.fromEntries(['click','open','reveal','finish','dombra'].filter(k=>ASSETS[k]).map(k=>{const a=new Audio(ASSETS[k]);a.volume=.35;return[k,a]}));
function later(fn,ms){const e=epoch,t=setTimeout(()=>{timers.delete(t);if(e===epoch)fn()},ms);timers.add(t)}
function stopAudio(){Object.values(audio).forEach(a=>{a.pause();try{a.currentTime=0}catch(e){}})}
function playSound(k){if(!sound||!audio[k])return;const a=audio[k];a.pause();a.currentTime=0;a.volume=.35;a.play().catch(()=>{});if(k==='dombra')later(()=>{let v=.35;const fade=()=>{if(!sound){a.pause();return}v-=.07;a.volume=Math.max(0,v);if(v>0)later(fade,35);else a.pause()};fade()},1800)}
function stop(){epoch++;timers.forEach(clearTimeout);timers.clear();stopAudio();document.querySelectorAll('.confetti').forEach(e=>e.remove());document.querySelectorAll('.bag').forEach(b=>b.classList.remove('open','revealed','shake'));busy=false;if($('result').open)$('result').close()}
function persist(){if(state)set(KEY,JSON.stringify(state))}
function soundUI(){$('sound').textContent='Дыбыс: '+(sound?'қосулы':'өшірулі');$('sound').setAttribute('aria-pressed',String(sound))}$('sound').onclick=()=>{sound=!sound;if(!sound)stopAudio();set('qorzhyn-sound',sound?'on':'off');soundUI()};soundUI();
$('fullscreen').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen?.()}catch(e){}};document.addEventListener('fullscreenchange',()=>$('fullscreen').textContent=document.fullscreenElement?'Экраннан шығу':'Толық экран');
function image(key,cls='',alt=''){return `<img class="${cls}" src="${ASSETS[key]||''}" alt="${esc(alt)}" data-image="${key}">`}
function fallbacks(root=document){root.querySelectorAll('img[data-image]').forEach(im=>{const fn=()=>{if(!im.isConnected)return;const d=document.createElement('span');const key=im.dataset.image;if(key==='body')d.className='body fallback-pouch';else if(key==='flap'){im.parentElement.classList.add('fallback-flap');im.remove();return}else{d.className=im.className+' fallback-emblem';d.textContent=GROUPS.find(g=>g.key===key)?.symbol||'✦';d.setAttribute('role','img');d.setAttribute('aria-label',im.alt)}im.replaceWith(d)};im.onerror=fn;if(im.complete&&!im.naturalWidth)fn()})}
function showSection(id){for(const x of ['setup','resume','play','summary'])$(x).hidden=x!==id;$('restart').hidden=!['play','summary'].includes(id);$('progress').hidden=!['play','summary'].includes(id)}
function parseNames(){return $('names').value.split(/\r?\n/).map(s=>s.trim()).filter(Boolean)}
function draft(){set(DRAFT,JSON.stringify({groupCount:Number($('groupCount').value),mode,count:$('count').value,names:$('names').value}))}
function preview(){setGroups(Number($('groupCount').value));const gc=GROUPS.length;const names=parseNames(),n=mode==='names'?names.length:Number($('count').value);$('namesInfo').textContent=`Тізімде: ${names.length} оқушы`;const dup=names.filter((x,i)=>names.findIndex(n=>n.toLocaleLowerCase()===x.toLocaleLowerCase())!==i);$('duplicates').textContent=dup.length?'Ескерту: қайталанған аты-жөндер бар: '+[...new Set(dup)].join(', ')+'. Олар тізімде сақталады.':'';const valid=Number.isInteger(n)&&n>=4&&n<=60;$('plan').innerHTML=GROUPS.map((g,i)=>`<div>${g.name}<b>${valid?Math.floor(n/gc)+(i<n%gc?1:0):'—'}</b></div>`).join('');$('error').textContent='';draft()}
function setMode(m){mode=m;$('modeCount').setAttribute('aria-pressed',String(m==='count'));$('modeNames').setAttribute('aria-pressed',String(m==='names'));$('countField').hidden=m!=='count';$('namesField').hidden=m!=='names';preview()}
$('groupCount').onchange=preview;
$('modeCount').onclick=()=>setMode('count');$('modeNames').onclick=()=>setMode('names');$('count').oninput=preview;$('names').oninput=preview;
function makeBags(){$('bags').innerHTML=GROUPS.map((_,i)=>`<button class="bag" data-bag="${i}" aria-label="${['Бірінші','Екінші','Үшінші','Төртінші'][i]} қоржынды таңдау"><span class="glow"></span><span class="prize"></span>${image('body','body')}<span class="flap">${image('flap')}</span><span class="number">${i+1}</span></button>`).join('');$('bags').querySelectorAll('button').forEach((b,i)=>b.onclick=()=>assign(i));fallbacks($('bags'))}
function teamMarkup(summary=false){return GROUPS.map((g,i)=>{const list=state.done.flatMap((t,j)=>t===i?[state.names[j]]:[]);return `<section class="team" style="--team:${g.color}"><div class="team-head">${image(g.key,'',g.name+' тобының белгісі')}<div><h2>${g.name}</h2><small>${list.length}/${state.cap[i]}</small></div></div><progress max="${state.cap[i]}" value="${list.length}" aria-label="${g.name}: ${list.length}/${state.cap[i]}"></progress>${list.length?'<ol>'+list.map(n=>'<li>'+esc(n)+'</li>').join('')+'</ol>':'<p class="empty">Оқушылар күтілуде</p>'}</section>`}).join('')}
function updateTeams(){$('progress').textContent=`Бөлінді: ${state.done.length}/${state.names.length}`;$('liveTeams').innerHTML=teamMarkup();fallbacks($('liveTeams'))}
function renderPlay(){showSection('play');updateTeams();$('turn').textContent=state.phase==='result'?'Таңдау жасалды':`Кезек: ${state.names[state.done.length]||''}`;$('status').textContent=state.phase==='result'?'Тобыңды есте сақтап, келесі оқушыға кезек бер.':'Кез келген қоржынды таңдаңдар.';$('bags').querySelectorAll('button').forEach(b=>b.disabled=state.phase!=='choose'||busy)}
function start(names,m){stop();setGroups(Number($('groupCount').value));state=new Division(names,m,GROUPS.length);persist();makeBags();renderPlay();$('bags').querySelector('button').focus()}
$('start').onclick=()=>{const n=Number($('count').value),names=mode==='names'?parseNames():Array.from({length:Number.isInteger(n)&&n>=4&&n<=60?n:0},(_,i)=>`${i+1}-оқушы`);if(names.length<4||names.length>60||mode==='count'&&(!Number.isInteger(n)||!$('count').value.trim())){$('error').textContent=mode==='names'?'Әр жолға бір оқушыдан енгізіңіз. Тізімде 4–60 оқушы болуы керек.':'Оқушылар санын 4 пен 60 аралығындағы бүтін санмен енгізіңіз.';return}start(names,mode)};
function showResult(){busy=false;const idx=state.done.length-1,g=GROUPS[state.done[idx]],name=state.names[idx];$('result').style.setProperty('--team',g.color);$('resultContent').innerHTML=image(g.key,'result-img',g.name+' тобының белгісі')+`<p class="result-name">${state.mode==='names'?esc(name)+', сенің тобың —':'Сенің тобың —'}</p><h2>${g.name}</h2><p class="help">Бірге ойлаймыз, бірге үйренеміз!</p>`;$('next').textContent=state.done.length===state.names.length?'Топтарды көру':'Келесі оқушы';fallbacks($('result'));if(!$('result').open)$('result').showModal();renderPlay()}
function assign(bag){if(busy||!state||!state.assign(bag))return;busy=true;persist();renderPlay();const b=$('bags').children[bag],g=GROUPS[state.done.at(-1)];b.querySelector('.prize').innerHTML=image(g.key,'',g.name)+`<b style="color:${g.color}">${g.name}</b>`;fallbacks(b);playSound('click');b.classList.add('shake');later(()=>{b.classList.remove('shake');b.classList.add('open');playSound('open')},reduced?0:300);later(()=>{b.classList.add('revealed');playSound(audio.dombra?'dombra':'reveal')},reduced?0:850);later(showResult,reduced?20:1600)}
$('result').addEventListener('cancel',e=>e.preventDefault());
$('next').onclick=()=>{if(!state||state.phase!=='result')return;stop();state.next();persist();if(state.phase==='summary'){renderSummary();celebrate()}else{renderPlay();$('bags').querySelector('button').focus()}};
function renderSummary(){showSection('summary');$('summaryTitle').textContent=GROUPS.length+' топ — бір мақсат!';$('progress').textContent=`Бөлінді: ${state.done.length}/${state.names.length}`;$('summaryCount').textContent=`${state.names.length} оқушы ${GROUPS.length} топқа бөлінді.`;$('finalTeams').innerHTML=teamMarkup(true);fallbacks($('finalTeams'));$('copyStatus').textContent=''}
function celebrate(){playSound('finish');if(reduced)return;for(let i=0;i<32;i++){const c=document.createElement('i');c.className='confetti';c.style.background=['#dbb155','#52bfc5','#376daf'][i%3];c.style.left=Math.random()*100+'vw';c.style.animationDelay=Math.random()*.5+'s';document.body.append(c);later(()=>c.remove(),3200)}}
function ask(message,action){confirmAction=action;$('confirmText').textContent=message;$('confirm').showModal()}
$('yes').onclick=()=>{$('confirm').close();const a=confirmAction;confirmAction=null;a?.()};$('no').onclick=()=>{$('confirm').close();confirmAction=null};
function backToSetup(){stop();state=null;saved=null;remove(KEY);showSection('setup');preview()}
$('restart').onclick=()=>ask('Қазіргі бөлуді өшіріп, қайта бастағыңыз келе ме?',backToSetup);
$('reshuffle').onclick=()=>ask('Сол оқушыларды жаңадан топқа бөлгіңіз келе ме?',()=>start(state.names,state.mode));
function resultText(){return GROUPS.length+' топ — бір мақсат!\n\n'+GROUPS.map((g,i)=>g.name+'\n'+state.done.flatMap((t,j)=>t===i?[state.names[j]]:[]).map((n,j)=>`${j+1}. ${n}`).join('\n')).join('\n\n')}
$('copy').onclick=async()=>{const text=resultText();try{if(!navigator.clipboard?.writeText)throw Error();await navigator.clipboard.writeText(text);$('copyStatus').textContent='Нәтиже көшірілді!'}catch(e){$('copyText').value=text;$('copyDialog').showModal();$('copyText').select()}};$('copyClose').onclick=()=>$('copyDialog').close();
$('print').onclick=()=>{$('printArea').innerHTML='<h1>'+GROUPS.length+' топ — бір мақсат!</h1><div class="print-grid">'+GROUPS.map((g,i)=>'<section><h2>'+g.name+'</h2><ol>'+state.done.flatMap((t,j)=>t===i?['<li>'+esc(state.names[j])+'</li>']:[]).join('')+'</ol></section>').join('')+'</div>';window.print()};
$('continue').onclick=()=>{state=saved;saved=null;setGroups(state.groupCount);$('groupCount').value=state.groupCount;makeBags();if(state.phase==='summary')renderSummary();else{renderPlay();if(state.phase==='result'){const b=$('bags').children[state.bag],g=GROUPS[state.done.at(-1)];b.classList.add('open','revealed');b.querySelector('.prize').innerHTML=image(g.key)+`<b>${g.name}</b>`;showResult()}}};$('newSession').onclick=()=>ask('Сақталған бөлуді өшіріп, жаңадан бастағыңыз келе ме?',backToSetup);
try{const d=JSON.parse(get(DRAFT));if(d){$('groupCount').value=[2,3,4].includes(Number(d.groupCount))?d.groupCount:4;$('count').value=d.count??24;$('names').value=d.names??'';mode=d.mode==='names'?'names':'count'}}catch(e){}setMode(mode);makeBags();try{saved=Division.restore(JSON.parse(get(KEY)))}catch(e){}if(saved){$('resumeInfo').textContent=`Бөлінді: ${saved.done.length}/${saved.names.length}. Нәтижені жоғалтпай жалғастыра аласыз.`;showSection('resume')}else showSection('setup');
